import { promises as fs } from 'node:fs'
import path from 'node:path'
import { randomBytes } from 'node:crypto'

export type BookStatus = 'reading' | 'finished'

export type Book = {
  id: string
  title: string
  author: string
  notes: string
  status: BookStatus
  addedAt: string
  finishedAt: string | null
}

export type NewBook = Pick<Book, 'title' | 'author' | 'notes'>

export const LIMITS = { title: 200, author: 200, notes: 10_000 } as const

export class ValidationError extends Error {}

// Read at call time so tests (or a deployment) can point at a different file.
function dataFile(): string {
  return process.env.BOOKS_FILE ?? path.join(process.cwd(), 'data', 'books.json')
}

async function readAll(): Promise<Book[]> {
  let raw: string
  try {
    raw = await fs.readFile(dataFile(), 'utf8')
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === 'ENOENT') return []
    throw err
  }
  // A corrupt file is an error, not an empty list: treating it as empty would
  // make the next write silently wipe every book.
  const parsed: unknown = JSON.parse(raw)
  if (!Array.isArray(parsed)) {
    throw new Error(`${dataFile()} does not contain a list of books`)
  }
  return parsed as Book[]
}

async function writeAll(books: Book[]): Promise<void> {
  const file = dataFile()
  await fs.mkdir(path.dirname(file), { recursive: true })
  // Write to a temp file and rename so a crash mid-write can't leave a
  // half-written books.json behind.
  const tmp = `${file}.${process.pid}.${Date.now()}.tmp`
  await fs.writeFile(tmp, JSON.stringify(books, null, 2) + '\n', 'utf8')
  await fs.rename(tmp, file)
}

// Serialise read-modify-write cycles so two requests arriving together can't
// both read the old list and have one overwrite the other's change.
let queue: Promise<unknown> = Promise.resolve()

function mutate<T>(fn: (books: Book[]) => { books: Book[]; result: T }): Promise<T> {
  const run = queue.then(async () => {
    const { books, result } = fn(await readAll())
    await writeAll(books)
    return result
  })
  queue = run.catch(() => {})
  return run
}

export async function listBooks(): Promise<Book[]> {
  return readAll()
}

export async function getBook(id: string): Promise<Book | null> {
  const books = await readAll()
  return books.find((b) => b.id === id) ?? null
}

function clean(value: string, field: keyof typeof LIMITS, required: boolean): string {
  const trimmed = value.trim()
  if (required && !trimmed) {
    throw new ValidationError(`Please enter a ${field}.`)
  }
  if (trimmed.length > LIMITS[field]) {
    throw new ValidationError(`The ${field} can be at most ${LIMITS[field]} characters.`)
  }
  return trimmed
}

export async function addBook(input: NewBook): Promise<Book> {
  const book: Book = {
    id: randomBytes(9).toString('base64url'),
    title: clean(input.title, 'title', true),
    author: clean(input.author, 'author', true),
    notes: clean(input.notes, 'notes', false),
    status: 'reading',
    addedAt: new Date().toISOString(),
    finishedAt: null,
  }
  return mutate((books) => ({ books: [...books, book], result: book }))
}

export async function markFinished(id: string): Promise<Book | null> {
  return mutate((books) => {
    const book = books.find((b) => b.id === id)
    if (!book) return { books, result: null }
    if (book.status !== 'finished') {
      book.status = 'finished'
      book.finishedAt = new Date().toISOString()
    }
    return { books, result: book }
  })
}

