'use server'

import { revalidatePath } from 'next/cache'
import { addBook, markFinished, ValidationError } from '@/lib/books'

export type AddBookState = { error: string | null; savedAt: number | null }

function field(formData: FormData, name: string): string {
  const value = formData.get(name)
  return typeof value === 'string' ? value : ''
}

export async function addBookAction(
  _prev: AddBookState,
  formData: FormData,
): Promise<AddBookState> {
  try {
    await addBook({
      title: field(formData, 'title'),
      author: field(formData, 'author'),
      notes: field(formData, 'notes'),
    })
  } catch (err) {
    if (err instanceof ValidationError) return { error: err.message, savedAt: null }
    throw err
  }
  revalidatePath('/')
  return { error: null, savedAt: Date.now() }
}

export async function markFinishedAction(formData: FormData): Promise<void> {
  const id = field(formData, 'id')
  await markFinished(id)
  revalidatePath('/')
  revalidatePath(`/books/${id}`)
}

