'use client'

import { useActionState } from 'react'
import { addBookAction, type AddBookState } from './actions'
import { LIMITS } from '@/lib/limits'

const initialState: AddBookState = {
  error: null,
  values: { title: '', author: '', notes: '' },
}

export function AddBookForm() {
  const [state, formAction, pending] = useActionState(addBookAction, initialState)

  return (
    <form action={formAction} className="card add-form">
      <h2>Add a book</h2>
      <label>
        Title
        <input
          name="title"
          required
          maxLength={LIMITS.title}
          defaultValue={state.values.title}
        />
      </label>
      <label>
        Author
        <input
          name="author"
          required
          maxLength={LIMITS.author}
          defaultValue={state.values.author}
        />
      </label>
      <label>
        Notes <span className="muted">(optional)</span>
        <textarea
          name="notes"
          rows={4}
          maxLength={LIMITS.notes}
          defaultValue={state.values.notes}
        />
      </label>
      {state.error && (
        <p className="error" role="alert">
          {state.error}
        </p>
      )}
      <button type="submit" disabled={pending}>
        {pending ? 'Adding…' : 'Add to currently reading'}
      </button>
    </form>
  )
}

