import Link from 'next/link'
import { connection } from 'next/server'
import { listBooks, type Book } from '@/lib/books'
import { AddBookForm } from './add-book-form'
import { MarkFinishedButton } from './mark-finished-button'

function newestFirst(key: 'addedAt' | 'finishedAt') {
  return (a: Book, b: Book) => (b[key] ?? '').localeCompare(a[key] ?? '')
}

export default async function HomePage() {
  // The book list lives in a file that changes at runtime, so never prerender.
  await connection()
  const books = await listBooks()
  const reading = books.filter((b) => b.status === 'reading').sort(newestFirst('addedAt'))
  const finished = books.filter((b) => b.status === 'finished').sort(newestFirst('finishedAt'))

  return (
    <>
      <section>
        <h2>Currently reading</h2>
        {reading.length === 0 ? (
          <p className="muted">Nothing on the go. Add a book below.</p>
        ) : (
          <ul className="book-list">
            {reading.map((book) => (
              <li key={book.id}>
                <BookLink book={book} />
                <MarkFinishedButton id={book.id} />
              </li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <h2>Finished</h2>
        {finished.length === 0 ? (
          <p className="muted">No finished books yet.</p>
        ) : (
          <ul className="book-list">
            {finished.map((book) => (
              <li key={book.id}>
                <BookLink book={book} />
              </li>
            ))}
          </ul>
        )}
      </section>

      <AddBookForm />
    </>
  )
}

function BookLink({ book }: { book: Book }) {
  return (
    <Link href={`/books/${book.id}`} className="book-link">
      <span className="title">{book.title}</span>
      <span className="muted">{book.author}</span>
    </Link>
  )
}

