import type { Metadata } from 'next'
import Link from 'next/link'
import { notFound } from 'next/navigation'
import { connection } from 'next/server'
import { getBook } from '@/lib/books'
import { MarkFinishedButton } from '../../mark-finished-button'
import { CopyLinkButton } from './copy-link-button'

export async function generateMetadata(props: PageProps<'/books/[id]'>): Promise<Metadata> {
  await connection()
  const { id } = await props.params
  const book = await getBook(id)
  return book ? { title: `${book.title} by ${book.author}` } : {}
}

function formatDate(iso: string): string {
  return new Date(iso).toLocaleDateString('en-GB', { dateStyle: 'long' })
}

export default async function BookPage(props: PageProps<'/books/[id]'>) {
  await connection()
  const { id } = await props.params
  const book = await getBook(id)
  if (!book) notFound()

  return (
    <article className="card">
      <p>
        <Link href="/">← All books</Link>
      </p>
      <h2 className="book-title">{book.title}</h2>
      <p className="author">by {book.author}</p>
      <p className="muted">
        {book.status === 'finished' && book.finishedAt
          ? `Finished ${formatDate(book.finishedAt)}`
          : `Reading since ${formatDate(book.addedAt)}`}
      </p>

      <h3>Notes</h3>
      {book.notes ? (
        <p className="notes">{book.notes}</p>
      ) : (
        <p className="muted">No notes.</p>
      )}

      <div className="actions">
        <CopyLinkButton />
        {book.status === 'reading' && <MarkFinishedButton id={book.id} />}
      </div>
    </article>
  )
}

