import { markFinishedAction } from './actions'

export function MarkFinishedButton({ id }: { id: string }) {
  return (
    <form action={markFinishedAction}>
      <input type="hidden" name="id" value={id} />
      <button type="submit" className="secondary">
        Mark as finished
      </button>
    </form>
  )
}

import Link from 'next/link'
import { connection } from 'next/server'
import { listBooks, type Book } from '@/lib/books'
import { AddBookForm } from './add-book-form'
import { MarkFinishedButton } from './mark-finished-button'

function newestFirst(key: 'addedAt' | 'finishedAt') {
  return (a: Book, b: Book) => (b[key] ?? '').localeCompare(a[key] ?? '')
}

export default async function HomePage() {
  // The book list lives in a file that changes at runtime, so never prerender.
  await connection()
  const books = await listBooks()
  const reading = books.filter((b) => b.status === 'reading').sort(newestFirst('addedAt'))
  const finished = books.filter((b) => b.status === 'finished').sort(newestFirst('finishedAt'))

  return (
    <>
      <section>
        <h2>Currently reading</h2>
        {reading.length === 0 ? (
          <p className="muted">Nothing on the go. Add a book below.</p>
        ) : (
          <ul className="book-list">
            {reading.map((book) => (
              <li key={book.id}>
                <BookLink book={book} />
                <MarkFinishedButton id={book.id} />
              </li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <h2>Finished</h2>
        {finished.length === 0 ? (
          <p className="muted">No finished books yet.</p>
        ) : (
          <ul className="book-list">
            {finished.map((book) => (
              <li key={book.id}>
                <BookLink book={book} />
              </li>
            ))}
          </ul>
        )}
      </section>

      <AddBookForm />
    </>
  )
}

function BookLink({ book }: { book: Book }) {
  return (
    <Link href={`/books/${book.id}`} className="book-link">
      <span className="title">{book.title}</span>
      <span className="muted">{book.author}</span>
    </Link>
  )
}

import type { Metadata } from 'next'
import Link from 'next/link'
import { notFound } from 'next/navigation'
import { connection } from 'next/server'
import { getBook } from '@/lib/books'
import { MarkFinishedButton } from '../../mark-finished-button'
import { CopyLinkButton } from './copy-link-button'

export async function generateMetadata(props: PageProps<'/books/[id]'>): Promise<Metadata> {
  await connection()
  const { id } = await props.params
  const book = await getBook(id)
  return book ? { title: `${book.title} by ${book.author}` } : {}
}

function formatDate(iso: string): string {
  return new Date(iso).toLocaleDateString('en-GB', { dateStyle: 'long' })
}

export default async function BookPage(props: PageProps<'/books/[id]'>) {
  await connection()
  const { id } = await props.params
  const book = await getBook(id)
  if (!book) notFound()

  return (
    <article className="card">
      <p>
        <Link href="/">← All books</Link>
      </p>
      <h2 className="book-title">{book.title}</h2>
      <p className="author">by {book.author}</p>
      <p className="muted">
        {book.status === 'finished' && book.finishedAt
          ? `Finished ${formatDate(book.finishedAt)}`
          : `Reading since ${formatDate(book.addedAt)}`}
      </p>

      <h3>Notes</h3>
      {book.notes ? (
        <p className="notes">{book.notes}</p>
      ) : (
        <p className="muted">No notes.</p>
      )}

      <div className="actions">
        <CopyLinkButton />
        {book.status === 'reading' && <MarkFinishedButton id={book.id} />}
      </div>
    </article>
  )
}

'use client'

import { useState } from 'react'

export function CopyLinkButton() {
  const [copied, setCopied] = useState(false)

  async function copy() {
    const url = window.location.href
    try {
      await navigator.clipboard.writeText(url)
      setCopied(true)
      setTimeout(() => setCopied(false), 2000)
    } catch {
      // Clipboard access needs HTTPS (or localhost); fall back to showing the URL.
      window.prompt('Copy this link:', url)
    }
  }

  return (
    <button type="button" onClick={copy}>
      {copied ? 'Link copied' : 'Copy link to share'}
    </button>
  )
}

