import { promises as fs } from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import { afterEach, beforeEach, describe, expect, it } from 'vitest'
import { addBook, getBook, listBooks, markFinished, ValidationError } from './books'

let dir: string
let file: string

beforeEach(async () => {
  dir = await fs.mkdtemp(path.join(os.tmpdir(), 'books-'))
  file = path.join(dir, 'nested', 'books.json')
  process.env.BOOKS_FILE = file
})

afterEach(async () => {
  delete process.env.BOOKS_FILE
  await fs.rm(dir, { recursive: true, force: true })
})

const dune = { title: 'Dune', author: 'Frank Herbert', notes: 'Spice.' }

describe('books store', () => {
  it('starts empty when there is no file yet', async () => {
    expect(await listBooks()).toEqual([])
  })

  it('adds a book as currently reading and writes it to disk', async () => {
    const book = await addBook({ title: '  Dune ', author: 'Frank Herbert', notes: '' })
    expect(book).toMatchObject({ title: 'Dune', status: 'reading', finishedAt: null })
    expect(book.id).toMatch(/^[\w-]{12}$/)

    const onDisk = JSON.parse(await fs.readFile(file, 'utf8'))
    expect(onDisk).toEqual([book])
    expect(await getBook(book.id)).toEqual(book)
  })

  it('marks a book as finished', async () => {
    const book = await addBook(dune)
    const done = await markFinished(book.id)
    expect(done?.status).toBe('finished')
    expect(done?.finishedAt).toBeTruthy()
    expect((await getBook(book.id))?.status).toBe('finished')
  })

  it('returns null for unknown ids', async () => {
    expect(await getBook('nope')).toBeNull()
    expect(await markFinished('nope')).toBeNull()
  })

  it('rejects missing or overlong fields', async () => {
    await expect(addBook({ ...dune, title: '   ' })).rejects.toThrow(ValidationError)
    await expect(addBook({ ...dune, author: '' })).rejects.toThrow(ValidationError)
    await expect(addBook({ ...dune, notes: 'x'.repeat(10_001) })).rejects.toThrow(ValidationError)
    expect(await listBooks()).toEqual([])
  })

  it('does not lose books when several are added at once', async () => {
    await Promise.all(
      Array.from({ length: 20 }, (_, i) => addBook({ ...dune, title: `Book ${i}` })),
    )
    expect(await listBooks()).toHaveLength(20)
  })

  it('refuses to overwrite a corrupt file', async () => {
    await fs.mkdir(path.dirname(file), { recursive: true })
    await fs.writeFile(file, '{ not json')
    await expect(addBook(dune)).rejects.toThrow()
    expect(await fs.readFile(file, 'utf8')).toBe('{ not json')
  })
})

